const MAP_NOTES27_DATA={"schemaVersion":1,"edition":"Map Notes27: port refinements","createdDate":"2026-11-16","baseCatalogueSha256":"6e7991bcd8ab00e472a320a7afc7aaf225a2300376d6f5af80441dcc37879b86","policy":{"additiveOnly":true,"changesOriginalCatalogue":false,"changesCoordinates":false,"changesActivityWindows":false,"addsRoutesOrHarbourGeometry":false,"connectionsMeaning":"Related reading and source-supported context, not newly drawn roads, voyages, trade-volume estimates or political control."},"sources":[{"id":"P27-S-BYBLOS-2025","title":"Francis-Allouche (2025), Byblos et la mer: les abords maritimes et le système portuaire antique","url":"https://aibl.fr/collections/tome-65-byblos-et-la-mer-les-abords-maritimes-et-le-systeme-portuaire-antique/","authority":"Académie des Inscriptions et Belles-Lettres; monograph by Martine Francis-Allouche with preface by Nicolas Grimal","locator":"Présentation, final paragraph: twelve field operations; buried basin at southern foot of Byblos acropolis","access":"Actual institutional monograph presentation inspected 2026-11-16. Full 376-page book not accessed. Reported confirmation is qualitative; no basin geometry or construction-year chronology copied."},{"id":"P27-S-TYRE-2005","title":"Marriner et al. (2005), Geoarchaeology of Tyre’s ancient northern harbour, Phoenicia","url":"https://doi.org/10.1016/j.jas.2005.03.019","alternateUrls":["https://www.ancientportsantiques.com/wp-content/uploads/Documents/PLACES/Levant/Tyr/Tyr-Marriner2005.pdf"],"authority":"Primary research paper, Journal of Archaeological Science 32 (2005),1302–1327","locator":"Abstract and introduction, printed pp. 1302–1303; geomorphological conclusions, printed p. 1322","access":"Publisher indexed abstract inspected; direct publisher request 403. Full 26-page primary-paper PDF inspected via Ancient Ports Antiques copy. Only broad natural shelter and changing basin context used; no chronology inferred from unconverted BP values and no geometry digitized."},{"id":"P27-S-HST-2015","title":"Devillers, Brown and Morhange (2015), Paleo-environmental evolution of the Larnaca Salt Lakes and second-millennium settlement","url":"https://doi.org/10.1016/j.jasrep.2014.11.004","alternateUrls":["https://cris.haifa.ac.il/en/publications/paleo-environmental-evolution-of-the-larnaca-salt-lakes-cyprus-an/"],"authority":"Primary coring/geomorphological research, Journal of Archaeological Science: Reports 1 (2015),73–80","locator":"Abstract, introduction, Natural channels section and conclusions","access":"Actual University of Haifa institutional abstract plus indexed publisher sections inspected. Direct publisher request 403. Primary study identifies an ancient lagoon and two natural channels; no channel vectors copied. Its c. 1600–1175 BCE interpretation remains attributed separately from newer expedition dating."},{"id":"P27-S-HST-GU2023","title":"University of Gothenburg (2023), Cyprus’s copper deposits and the harbour city of Hala Sultan Tekke","url":"https://www.gu.se/en/news/cypruss-copper-deposits-created-one-of-the-most-important-trade-hubs-in-the-bronze-age","authority":"University of Gothenburg; excavation director Peter M. Fischer explains the 2023 imports study","locator":"Large quantities of imported goods and Trade flourished for 500 years sections; description of well-protected harbour","access":"Actual university provider article inspected 2026-11-16. Explicit 1500–1150 BCE trade-hub interval independently corroborates the retained 26 commercial window. Imports are evidence of exchange connections, not proof of direct voyages from every find’s material source."},{"id":"P27-S-KITION-MISSION","title":"Kition: a capital city of Cyprus","url":"https://archeologie.culture.gouv.fr/proche-orient/en/kition-capital-city-of-Cyprus","authority":"French Ministry of Culture / French archaeological mission at Kition","locator":"Bamboula harbour: fourth-century BCE fleet shelter","access":"Primary/institutional provider indexed caption inspected 2026-11-16. Direct page initially returned only limited extract and later unexpected status. Used only for a scope warning: the famous fourth-century military harbour is later than the atlas 500 BCE endpoint; no new playable port phase is assigned."}],"relatedMetalNotes":[{"featureId":"P26-CENTER-KITION","brief":"At Kition, copper workshops near the sacred precinct form a production story distinct from the city’s later famous naval harbour.","detailParagraphs":["Copper processing in the Kathari workshops is documented in twelfth–eleventh-century BCE contexts. The often-illustrated military shipsheds at Bamboula date to the fourth century BCE, after this map’s 500 BCE endpoint; they represent a later chapter of the city’s maritime history."],"sourceIds":["P26-C-KITION","P26-C-KITION-12","P27-S-KITION-MISSION"],"relatedFeatureIds":["P26-CENTER-HST","P26-CENTER-ENKOMI"],"essentialCaution":"Later naval-harbour remains do not date the earlier copper workshops.","noticePolicy":{"brief":"","detail":"Kathari’s copper workshops and Bamboula’s later naval facilities have distinct archaeological contexts."},"sourceRefs":[{"sourceId":"P27-S-KITION-MISSION","locator":"Bamboula harbour caption: fourth-century BCE shipsheds"},{"sourceId":"P26-C-KITION","locator":"p.71, Northern Workshops and FloorII"}],"chronologyNote":"The Kathari copper-workshop evidence spans approximately 1200–1050 BCE. The fourth-century BCE naval-harbour remains belong to a later period."},{"featureId":"P26-CENTER-ENKOMI","brief":"Enkomi’s sampled workshops show copper being refined, remelted and cast, complementing the harbour and production stories elsewhere on Cyprus.","detailParagraphs":["Technical ceramics from Area III document later stages of copper production in particular excavated contexts. Refining, remelting and casting connect Enkomi to Cyprus’s broader copper economy; this study does not establish a harbour basin or a specific sea route."],"sourceIds":["P26-C-ENKOMI"],"relatedFeatureIds":["P26-CENTER-HST","P26-CENTER-KITION"],"essentialCaution":"AreaIII samples represent particular production contexts, not the whole city.","noticePolicy":{"brief":"","detail":"The Area III samples reveal particular production contexts, not the whole city’s industrial history."},"sourceRefs":[{"sourceId":"P26-C-ENKOMI","locator":"Tables 1–2 and conclusions: AreaIII sampled phases, secondary copper metallurgy"}],"chronologyNote":"The sampled phases span approximately 1650–1125 BCE. This broad range describes the archaeological contexts represented in the study, rather than continuous annual production."}],"noticePolicy":{"brief":"Show a concise positive description and a source-qualified activity/status line when needed. No generic missing-information section.","physicalContext":"A named mountain or river does not require an occupation-date warning. Keep physical/modern-reference meaning in accessible source notes and the existing map legend.","outsideEvidenceWindow":"Do not say absent, inactive, abandoned or no port. Say that the currently entered evidence concerns another period, with optional jump to it.","unlocatedGeometry":"No general warning is needed when only a representative symbol is drawn. Keep locator/boundary limits in full source details.","interpretiveClaims":"Keep words such as probable beside the claim they qualify. Keep source-specific chronology and port/workshop distinctions where the user reaches those claims.","unavailableRuntimeData":"Retain actual unavailable-source/failed-loader/retry notices because they describe a real technical condition.","emptyFields":"Omit empty sections rather than display generic no-information boxes. Preserve the original raw fields in full research/source records."},"ports":[{"featureId":"P26-CENTER-MAHADU","brief":"In a sheltered cove beside Ugarit, Mahadu joined the inland capital to Mediterranean shipping and coastal exchange.","setting":"Protected coastal cove near the inland capital of Ugarit.","role":"A coastal exchange settlement serving the capital’s maritime connections.","detailParagraphs":["The Ras Shamra–Ugarit mission reports marked growth from the fourteenth century BCE and probable commercial warehouses. Texts also refer to a quay and a harbour official, although harbourworks have not been excavated. The texts therefore add evidence of built facilities to the remains found on land.","Mahadu and Ugarit were complementary places: a coastal port and an inland capital. Their separate map points locate the settlements; the harbour basin, warehouses and connecting roads are not shown as excavated plans."],"sourceIds":["P26-C-MINET"],"chronologyNote":"The 1400–1300 BCE window describes the mission’s fourteenth-century commercial-growth reference, rather than the port’s complete lifespan.","essentialCaution":"Quays are text-attested; their excavated layout is not established here.","relatedFeatureIds":[],"relatedPlaceIds":["C20-MINET","UGARIT"],"noticePolicy":{"brief":"","detail":"Written evidence for quays and archaeological evidence for their layout answer different questions."},"sourceRefs":[{"sourceId":"P26-C-MINET","locator":"Minet el-Beida, paragraphs 1–3: cove, growth, warehouses and text-attested quay/harbour official"}]},{"featureId":"P26-CENTER-BYBLOS","brief":"Byblos connected the Lebanese timber hinterland with Egypt; research has identified a buried harbour basin below the city’s southern acropolis.","setting":"Lebanese coast below the city’s southern acropolis, opening toward a timber-rich hinterland.","role":"A maritime outlet linking hinterland timber and Egyptian demand.","detailParagraphs":["Byblos’s maritime importance is supported by textual and iconographic evidence for timber exports, chiefly toward Egypt. The 2025 presentation of Byblos et la mer reports that twelve archaeological and geoarchaeological operations confirmed a buried basin at the southern foot of the acropolis.","The buried basin gives the ancient waterfront a clearer setting. Its precise outline and construction date are not supplied here, and the present small harbour represents a different stage of the city’s coastal landscape."],"sourceIds":["P26-C-BYBLOS","P27-S-BYBLOS-2025"],"chronologyNote":"The 2000–1000 BCE window describes second-millennium maritime context; the basin finding is not independently dated here.","essentialCaution":"The buried basin is reported, but its ancient outline is not drawn.","relatedFeatureIds":["PE26-M-LEBANON"],"relatedPlaceIds":["PL668216"],"noticePolicy":{"brief":"","detail":"A buried basin is reported at the southern foot of the acropolis; its precise ancient outline and construction date remain separate questions."},"sourceRefs":[{"sourceId":"P27-S-BYBLOS-2025","locator":"Présentation, final paragraph: confirmed buried basin after twelve operations; no numeric construction date imported"}]},{"featureId":"P26-CENTER-TYRE","brief":"Tyre’s sheltered northern anchorage joins a coastal story of ships, storms and exchange linking Ugarit, Egypt and Acco.","setting":"A north-facing anchorage partly sheltered by sandstone reefs.","role":"Maritime exchange and shelter within the Levantine coastal network.","detailParagraphs":["Coring research describes a naturally sheltered Bronze Age cove, followed by major later changes to the northern harbour. Parts of the ancient basin now lie beneath the built city, so the modern fishing harbour is only part of the older port landscape.","In letter RS 18.031 the king of Tyre reports the rescue of cargo and crews from Ugaritic ships caught in a storm while bound for Egypt; the ships subsequently moored at Acco. This is a specific documented episode, not a measured shipping lane or an annual trade series."],"sourceIds":["P26-C-TYRE","P27-S-TYRE-2005"],"chronologyNote":"The 1400–1100 BCE window reflects the broad period of the Ugaritic writing corpus. It is not an exact date for the letter or the full lifespan of Tyre’s port.","essentialCaution":"The letter documents one episode; its exact calendar year is not assigned.","relatedFeatureIds":["P26-CENTER-MAHADU","PE26-R-LITANI"],"relatedPlaceIds":["PL678437","UGARIT"],"noticePolicy":{"brief":"The letter’s exact calendar year is not assigned.","detail":"The letter records a particular episode, with no exact calendar year assigned."},"sourceRefs":[{"sourceId":"P27-S-TYRE-2005","locator":"Abstract and printed pp.1302–1303: natural shelter and buried ancient harbour context"},{"sourceId":"P26-C-TYRE","locator":"Letter RS18.031, translation lines 10–25: storm, rescue of cargo/crews, Acco"}]},{"featureId":"P26-CENTER-DOR","brief":"Above Dor’s southern bay, harbour-related buildings and metalworking remains reveal a coastal town whose waterfront changed through successive phases.","setting":"Settlement edge above the southern bay.","role":"Harbour storage and craft production, documented in separate archaeological phases.","detailParagraphs":["The excavation project describes quays below Area D2 with a broad Late Bronze–Iron II attribution. In Persian-period phases, long narrow halls are interpreted as probable harbour storehouses. Their form and use need not represent every earlier waterfront phase.","Iron-processing debris belongs to a separate Assyrian-period industrial context. Coastal exchange and urban production form connected parts of Dor’s story, supported by remains from different phases."],"sourceIds":["P26-C-DOR","P26-C-DOR-IR"],"chronologyNote":"Iron-processing evidence belongs to the 730–600 BCE context; probable harbour storage is associated with the 539–332 BCE Persian period. The map’s 500 BCE endpoint does not mark the site’s abandonment.","essentialCaution":"The Persian-period halls are probable harbour stores; iron-processing evidence belongs to another phase.","relatedFeatureIds":[],"relatedPlaceIds":["PL678121"],"noticePolicy":{"brief":"","detail":"The halls’ harbour-storage function is probable, while the iron-processing remains belong to another phase."},"sourceRefs":[{"sourceId":"P26-C-DOR","locator":"AreaD2, opening, Persian phases 3–5 and IronIIb–c phases 6–7"}]},{"featureId":"P26-CENTER-HST","brief":"On an ancient sheltered lagoon, Hala Sultan Tekke brought copper production and imported goods into a far-reaching Late Bronze Age exchange hub.","setting":"Western shore of the ancient lagoon represented today by the Larnaca Salt Lakes.","role":"A harbour city connecting urban production with interregional exchange.","detailParagraphs":["Coring and geomorphological work confirms a second-millennium coastal lagoon with natural sea connections. This setting explains maritime access at a site that now appears beside salt lakes rather than an open harbour.","Imported ceramics and prestige goods, together with copper production, support wide exchange contacts. Objects from distant regions need not mean a direct voyage from each region to this port. Workshop dates remain distinct from the wider 1500–1150 BCE commercial horizon."],"sourceIds":["P26-C-HST","P26-C-HST-2026","P26-C-HST-WORK","P27-S-HST-2015","P27-S-HST-GU2023"],"chronologyNote":"The university’s 2023 account places the trade hub in 1500–1150 BCE. Devillers and colleagues’ 2015 study describes harbour use around 1600–1175 BCE, a different research interpretation. The CW1 workshop is dated separately to the thirteenth century BCE.","essentialCaution":"The ancient lagoon and the present salt-lake shoreline differ.","relatedFeatureIds":["P26-CENTER-KITION","P26-CENTER-ENKOMI"],"relatedPlaceIds":[],"noticePolicy":{"brief":"Ancient lagoon setting; the present shoreline is a modern reference.","detail":"The lagoon’s ancient sea connections explain a harbour setting that differs from today’s salt-lake shoreline. Port and workshop evidence have separate dates."},"sourceRefs":[{"sourceId":"P27-S-HST-2015","locator":"Abstract and conclusion: marine lagoon and source-specific harbour-use chronology"},{"sourceId":"P27-S-HST-GU2023","locator":"Large quantities of imported goods: explicit 1500–1150 BCE trade interval; not workshop dates"}]},{"featureId":"P26-CENTER-JARF","brief":"Wadi el-Jarf was an expedition harbour: boats, anchors and equipment waited here between voyages organized from the Nile valley.","setting":"Gulf of Suez coast near the eastern outlet of Wadi Araba.","role":"An intermittently used royal expedition base rather than a permanently busy commercial town.","detailParagraphs":["IFAO describes a deliberately sheltered coastal installation with a substantial jetty, expedition camps and stored anchors. Inland galleries held dismantled boats and equipment for reuse; those galleries and the waterfront were different parts of the complex.","The project places brief use under Snefru and Khufu and relates the harbour to state expeditions across the Gulf of Suez. The harbour connects the story of Nile-valley organisation with desert transport and coastal preparation; the precise journeys are not reconstructed here."],"sourceIds":["P26-C-JARF","P26-C-JARF-MAP"],"chronologyNote":"IFAO places this brief phase around 2600–2500 BCE, using its own approximate chronology for Snefru and Khufu. The expeditions were intermittent, with no securely established timetable of departures.","essentialCaution":"Intermittent expedition use; the plotted point represents the coastal complex.","relatedFeatureIds":[],"relatedPlaceIds":[],"noticePolicy":{"brief":"","detail":"Intermittent expedition use explains the storage galleries and equipment left between voyages."},"sourceRefs":[{"sourceId":"P26-C-JARF","locator":"Intermittent harbours, galleries/boat storage and early Fourth Dynasty chronological summary"}]},{"featureId":"P26-CENTER-BAHRAIN","brief":"Qal’at al-Bahrain joined a Dilmun urban centre to Gulf exchange, with storage and commerce linking the island to wider maritime networks.","setting":"Stratified settlement beside Bahrain’s northern coast.","role":"A Dilmun trading-port and urban centre within Gulf exchange.","detailParagraphs":["UNESCO identifies the site as a trading port and Dilmun capital, with successive residential, commercial and public remains. Bahrain’s institutional chronology places the capital’s commercial high point at the opening of the second millennium BCE, connecting Mesopotamia with the Indus sphere.","The archaeological tell contains many later phases. The conspicuous Portuguese fort and later channel structures belong to other periods and are not models for an Early Dilmun waterfront."],"sourceIds":["P26-C-BAHRAIN","P26-C-BAHRAIN-TIME","P26-C-BAHRAIN-MET"],"chronologyNote":"The 2000–1800 BCE window describes a commercial high point. It does not date harbour construction, imply an unchanging waterfront or mark the port’s closure.","essentialCaution":"The 2000–1800 BCE window represents commercial context, not the port’s full lifespan.","relatedFeatureIds":[],"relatedPlaceIds":["PL932478"],"noticePolicy":{"brief":"","detail":"Early Dilmun commerce, later harbour structures and the Portuguese fort belong to different periods."},"sourceRefs":[{"sourceId":"P26-C-BAHRAIN","locator":"Description and Outstanding Universal Value: port, tell and successive phases"},{"sourceId":"P26-C-BAHRAIN-TIME","locator":"Early Dilmun 2000/1800 BCE entry: capital’s commercial high point and Mesopotamia/Indus context"}]}]};
