function related(info){const items=[],seen=new Set();function add(id,label,action){if(id===info.id||seen.has(id))return;seen.add(id);items.push({label,action})}for(const id of info.relatedFeatureIds||[]){const f=featureById.get(id);if(f)add(id,f.name,()=>openFeature(id))}for(const id of info.relatedPlaceIds||[]){const p=placeById.get(id);if(p)add(id,p.name,()=>show({kind:'place',id}))}return items.slice(0,5)}
